import React, { useReducer, useState } from 'react'
import { FormattedMessage } from 'react-intl'
import * as Icons from '../icons'
import Delete from '../icons/Delete'
import MoreVert from '../icons/MoreVert'
import Search from '../icons/Search'
import List from '../List/List'
import Menu from '../Menu/Menu'
import type { MultiSelectValue } from './Actions'
import type { MultiSelectProps } from './MultiSelect'
import MultiSelect, { DisplayModes } from './MultiSelect'

export default {
  title: 'Components/MultiSelect',
  component: MultiSelect,
  argTypes: {
    label: { control: 'text' },
    helperText: { control: 'text' },
    dense: { control: 'boolean' },
    disabled: { control: 'boolean' },
    variant: {
      control: { type: 'select' },
      options: ['filled', 'outlined'],
    },
    endAdornment: {
      control: { type: 'select' },
      options: ['None', ...Object.keys(Icons)],
      mapping: { None: undefined, ...Icons },
    },
    startAdornment: {
      control: { type: 'select' },
      options: ['None', ...Object.keys(Icons)],
      mapping: { None: undefined, ...Icons },
    },
  },
}

const defaults = [
  { text: 'Contact Centre', value: '5' },
  { text: 'Staff', value: '10' },
  { text: 'Staff Plus', value: '13' },
  { text: 'Staff Advanced', value: '15' },
  { text: 'Manager', value: '20' },
  { text: 'Admin', value: '30' },
]

function useSuggestions(initial = defaults) {
  const [{ suggestions }, setState] = useReducer(
    (state, newState) => ({ ...state, ...newState }),
    { suggestions: initial },
  )
  const fetchSuggestions = (search) => {
    setState({
      suggestions: search
        ? initial.filter(({ text }) =>
            text.toLowerCase().match(search.toLowerCase()),
          )
        : initial,
    })
  }
  return [suggestions, setState, fetchSuggestions]
}

function Template(args: MultiSelectProps): JSX.Element {
  const [suggestions, setState, fetchSuggestions] = useSuggestions()

  return (
    <div className="w-64">
      <MultiSelect
        {...args}
        onChange={(event) => {
          setState((prevState) => ({ ...prevState, loading: true }))
          fetchSuggestions(event.target.value)
        }}
        onSelect={(value) => {
          // eslint-disable-next-line no-console
          console.log(JSON.stringify(value))
        }}
      >
        <MultiSelect.Group display={DisplayModes.Always}>
          {suggestions.map((suggestion) => (
            <MultiSelect.Suggestion
              key={`${suggestion.text}-auto1`}
              value={suggestion.value}
            >
              <span>{suggestion.text}</span>
            </MultiSelect.Suggestion>
          ))}
        </MultiSelect.Group>
      </MultiSelect>
    </div>
  )
}

// export const Default = Template.bind({})
const defaultArgs = {
  label: 'Multiselect',
  name: 'MultiSelect',
  variant: 'filled',
}

export const InitialSearchTerm = {
  render: Template,
  args: {
    ...defaultArgs,
    defaultDisplayValue: 'search',
    defaultValue: {
      '5': { label: 'Contact Centre', checked: true },
      '10': { label: 'Staff', checked: true },
      '13': { label: 'Staff Plus', checked: false },
    },
    endAdornment: Search,
    helperText: 'Some additional text',
    total: defaults.length,
  },
}

export const CompactDisplayValues = {
  render: Template,
  args: {
    ...defaultArgs,
    defaultValue: {
      '5': { label: 'Contact Centre', checked: true },
      '10': { label: 'Staff', checked: true },
      '13': { label: 'Staff Plus', checked: false },
    },
    helperText:
      'Multiple selections will show count of total in input on blur. Single selection will show text in input on blur.',
    total: defaults.length,
    dense: true,
  },
}

export function CustomList(): JSX.Element {
  const [suggestions, setState, fetchSuggestions] = useSuggestions()
  const [selections, setSelections] = useState<MultiSelectValue>({
    '5': { checked: true },
    '13': { checked: false },
    '15': { checked: true },
  })
  const [selectedRole, setSelectedRole] = useState({})
  const text = {}
  Object.entries(selections).forEach(([key, value]) => {
    defaults.forEach((role) => {
      if (key === role.value && value.checked) {
        text[key] = role.text
      }
    })
  })
  return (
    <div className="flex flex-col space-y-2">
      <h3>
        Shows how to use MultiSelect to manage selections but displaying them in
        a custom fashion, like a separated list. Multiselect is in compact mode
        in order to hide built-in suggestions.
      </h3>
      <div className="flex space-x-2">
        <div className="w-64">
          <MultiSelect
            defaultValue={selections}
            dense
            endAdornment={Search}
            helperText="Some helper text"
            label="Multiselect"
            name="MultiSelect"
            onChange={(event) => {
              setState((prevState) => ({ ...prevState, loading: true }))
              fetchSuggestions(event.target.value)
            }}
            onSelect={(value) => {
              setSelections(value)
            }}
            total={defaults.length}
            variant="filled"
          >
            <MultiSelect.Group display={DisplayModes.Always}>
              {suggestions.map((suggestion) => (
                <MultiSelect.Suggestion
                  key={`${suggestion.text}-auto1`}
                  value={suggestion.value}
                >
                  <span>{suggestion.text}</span>
                </MultiSelect.Suggestion>
              ))}
            </MultiSelect.Group>
          </MultiSelect>
          <List>
            {Object.entries(selections).map(([key, value]) =>
              value.checked ? (
                <div className="mb-2" key={`${key}`}>
                  <List.Item
                    endAdornment={
                      <Menu>
                        <Menu.Button icon label="moreActions" size="medium">
                          <MoreVert />
                        </Menu.Button>
                        <Menu.Items>
                          <Menu.Item
                            onClick={selections[key].handleClear}
                            startAdornment={Delete}
                          >
                            <FormattedMessage id="Ui.remove" />
                          </Menu.Item>
                        </Menu.Items>
                      </Menu>
                    }
                    endAdornmentType="element"
                    key={`${key}`}
                    onClick={() => setSelectedRole(value)}
                    primary={text[key]}
                    secondary="5 Services | Default Hours"
                    selected={value === selectedRole}
                  />
                </div>
              ) : null,
            )}
          </List>
        </div>
      </div>
    </div>
  )
}
